 'use strict';
(()=>{
 const D=window.GameData,K=window.CharacterData,V=window.CardVisuals,esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),number=n=>Number.isFinite(n)?Number(n.toFixed(1)):'—';
 function deckText(record){if(!record)return '편성 기록 없음';const counts={};for(const id of record.deck){const c=record.pool.find(x=>x.id===id),k=c.key+(c.upgraded?' ✦':'');counts[k]=(counts[k]||0)+1;}return Object.entries(counts).map(([k,n])=>esc(D.cards[k.replace(' ✦','')].name)+(k.endsWith(' ✦')?' ✦':'')+' × '+n).join(' · ');}
 function evidence(result,key){const x=result.insights,row=x?.rows?.[key],used=result.stats.cards[0][key]??row?.used??0,partial=!x||!x.complete,parts=[];if(row){for(const [k,label] of [['damage','피해'],['healed','실제 회복'],['shield','보호막 흡수'],['shared','피해 분담']])if(row[k]>0)parts.push((partial?'측정 구간 ':'')+label+' '+number(row[k]));if(row.blocks)parts.push('차단 '+row.blocks+'회');if(row.moved)parts.push('이동 '+row.moved+'명');if(row.boosts)parts.push('특성 강화 '+row.boosts+'회');}else if(result.stats.byCard?.[0]?.[key])parts.push('전체 피해 '+number(result.stats.byCard[0][key]));return {used,partial,status:used?'사용 '+used+'회'+(partial?' · 효과 일부 미기록':''):partial?'등장·미사용 여부 일부 미기록':row?.drawn?'손패 등장 · 미사용':'손패 미등장',parts};}
 function panel(result,origin=null,index=0){
  const x=result.insights,keys=[...new Set([...(result.practice?.deck.map(id=>result.practice.pool.find(c=>c.id===id).key)||result.traits?.keys||[]),...Object.keys(x?.rows||{}),...Object.keys(result.stats.cards[0])])].filter(k=>D.cards[k]),ko=x?.firstKO,top=Object.entries(result.stats.byCard?.[1]||{}).sort((a,b)=>b[1]-a[1]).slice(0,2);
  return `<section class="panel battle-insights"><h3>카드가 실제로 한 일</h3>${result.ultimateDiagnostics?`<details data-inline><summary>궁극기 보유 이유 · 관측 기록</summary>${result.ultimateDiagnostics.states.map(r=>`<p><strong>${esc(result.actors.find(a=>a.id===r.actor)?.name||r.actor)}</strong> · ${Object.entries(r.seconds).filter(([,n])=>n>.05).sort((a,b)=>b[1]-a[1]).map(([reason,n])=>esc(window.UltimateDiagnostics.labels[reason])+' '+number(n)+'초').join(' / ')||'준비한 궁극기 보유 구간 없음'}</p>`).join('')}${result.ultimateDiagnostics.rows.length?`<details data-inline><summary>최근 판단 순간</summary>${result.ultimateDiagnostics.rows.slice(-8).map(r=>`<p>${number(r.at)}초 · ${esc(result.actors.find(a=>a.id===r.actor)?.name||r.actor)} · ${esc(window.UltimateDiagnostics.labels[r.reason])}</p>`).join('')}</details>`:''}<p class="note">준비 완료 뒤 약 0.6초 간격과 실제 자동 선택 순간에 관측한 우선 이유입니다. 여러 조건이 겹칠 수 있으며, 선택 가능 기록은 실제 발동을 보장하지 않습니다.</p></details>`:''}${result.ultimates?`<p class="note">궁극기 · ${result.ultimates.actors.map(u=>esc(K.character(u.characterId).name)+' '+u.casts+'회 / 잔여 '+u.charge+'/100').join(' · ')} · 손패 미소비, 공유 명령 사용</p><details><summary>궁극기 발동·중단 기록</summary>${result.ultimates.history.map(h=>`<p>${number(h.at)}초 · ${esc(D.cards[h.key].name)} → ${esc(result.actors.find(a=>a.id===h.target)?.name)} · ${h.status==='completed'?'완료':h.status==='blocked'?'차단':'중단'} · 실제 피해 ${number(h.damage)}</p>`).join('')||'<p>이번 전투에서는 발동하지 않았습니다.</p>'}<p class="note">준비만 되면 즉시 발동하는 것이 아닙니다. 카드 가치, 대응 필요, 시전자 상태와 명령 기회를 함께 비교합니다.</p></details>`:''}${result.passives?.length?`<p class="note">${result.passives.map(p=>esc(K.character(p.characterId).name)+' · 조준 추가 사격 '+p.procs+'회').join(' / ')} · 기본 공격 피해에 포함</p>`:''}${result.tactic?`<p class="tactic-result">↗ 추격 릴레이 · 표식 전달 ${result.tactic.transfers}회 · 동료 후속 ${result.tactic.links}회 · 명령 +1초 적용 ${result.tactic.commands}회</p>`:''}${result.bossPhase?`<p class="note">보스 ${result.bossPhase.phase}단계 · HP 50% 전환 ${number(result.bossPhase.changedAt)}초 · 직선 패턴 적용 ${number(result.bossPhase.patternAt)}초 (이미 예고한 공격은 유지)</p>`:''}<p class="note">${x?x.complete?'이번 교전 전체 기록':number(x.from)+'초 이후 효과 부분 기록 · 사용 횟수는 전체 교전 기록':'이전 결과 · 사용과 피해만 기록. 회복·보호 기여는 미기록'}. 피해·회복은 실제 HP 변화이며 피해 분담은 피해 제거와 다릅니다. 보호막은 유지된 효과의 원본 카드에 귀속합니다.</p>${ko?`<p class="insight-threat">첫 전투불능 · ${esc(result.actors?.find(a=>a.id===ko.actor)?.name||K.characters[Number(ko.actor.slice(1))].name)} · ${number(ko.at)}초 · ${esc(ko.cause==='basic'?'적 기본 공격':(D.cards[ko.cause]||D.hostile[ko.cause]).name)}</p>`:''}<p class="note">적 기본 공격 피해 ${number(result.stats.basic[1])}${top.length?' / 피해가 큰 적 카드: '+top.map(([k,n])=>esc((D.cards[k]||D.hostile[k]).name)+' '+number(n)).join(' · '):''}. 주요 위협 정보이며 단일 패배 원인을 확정하지 않습니다.</p><details class="insight-breakdown"><summary>카드별 기여도 보기</summary><div class="insight-table-wrap"><table><thead><tr><th>카드</th><th>전체 사용</th><th>피해${x&&!x.complete?' · 측정 구간':''}</th><th>회복${x&&!x.complete?' · 측정 구간':''}</th><th>보호막 흡수</th><th>차단/분담</th><th>이동/특성 강화</th></tr></thead><tbody>${keys.map(k=>{const r=x?.rows[k],{used,status}=evidence(result,k);return `<tr><td><strong>${D.cards[k].source==='ultimate'?'궁극기 · ':''}${esc(D.cards[k].name)}</strong>${D.cards[k].source==='ultimate'?'':V.badges(k)}<small>${status}${x&&r?.drawn?' · 손패 등장 '+r.drawn+'회':''}</small></td><td>${used}회</td><td>${number(x?r?.damage||0:result.stats.byCard?.[0]?.[k]||0)}</td><td>${x?number(r?.healed||0):'—'}</td><td>${x?number(r?.shield||0):'—'}</td><td>${x?(r?.blocks||0)+'회 / '+number(r?.shared||0):'—'}</td><td>${x?(r?.moved||0)+'명 / '+(r?.boosts||0)+'회':'—'}</td></tr>`;}).join('')}</tbody></table></div><p class="note">미사용은 약한 카드라는 뜻이 아닙니다. 손패·발동 조건·시전자 상태·오토 우선순위가 영향을 줍니다. 도발·강화 등 수치로 합산되지 않는 지원은 사용/특성 기록을 함께 확인하세요.</p></details><details><summary>교전 시작 덱과 조건</summary><p>${deckText(result.practice)}</p>${result.practice?`<p class="note">시드 ${result.practice.config.seed} · 시작 HP ${result.practice.config.hp.map(number).join(' / ')} · 레벨 ${result.practice.config.levels.join('/')} · 대표 운용 ${result.practice.config.signatureMode==='guardDance'?'수호 검무':'기본'} · 태세 ${result.practice.config.stances.map((n,i)=>esc((result.practice.config.party?K.character(result.practice.config.party[i].characterId):K.characters[i]).stances[n])).join(' / ')}</p>`:''}</details>${origin&&result.practice?`<button class="primary" data-action="practice-open" data-origin="${origin}" data-result="${index}">이 조건으로 덱 수정·연습</button>`:origin?'<p class="note">이전 교전은 시작 조건 미기록 · 다음 교전부터 연습 가능</p>':''}</section>`;
 }
 function summary(r){return `${r.winner===0?'승리':esc(r.endReason||'패배')} · ${number(r.time)}초 · 남은 HP ${number(r.hp.reduce((n,h)=>n+h,0))} · 실제 회복 ${number(r.stats.healed[0])} · 차단 ${r.stats.blocked[0]}회${r.ultimates?' · 궁극기 '+r.ultimates.actors.reduce((n,u)=>n+u.casts,0)+'회':''}`;}
 window.BattleInsights={panel,deckText,summary,evidence};
})();
